pug:
table.row.brad-full.iq-combo-card-panel-list(role="presentation")
    tr
        td.wrapper.last.offset-by-one
            table.ten.columns(role="presentation")
                tr
                    td.text-pad-small.pb44.pt44
                        p.iq-combo-card-panel-list--title.pb16 {{ title }}
                        p.iq-combo-card-panel-list--text.pb32 {{ body }}
                        .iq-combo-card-panel-list--panel(style="background-image:url('{{ panel_image }}')")
                            .iq-combo-card-panel-list--copy
                                p.iq-combo-card-panel-list--text {{ panel_text }}
                            img.iq-combo-card-panel-list--mob-img(src="{{ panel_mobile_image }}" alt="")
                        ul.iq-combo-card-panel-list--list
                            li.iq-combo-card-panel-list--text.pb8 {{ item_1 }}
                            li.iq-combo-card-panel-list--text {{ item_2 }}
                        .h-40 &nbsp;
                        table.iq-combo-card-panel-list--w280(align="center" role="presentation" style="border-collapse:initial")
                            tr
                                td.iq-combo-card-panel-list--butt(style="padding:0")
                                    a.iq-combo-card-panel-list--butt-link(href="{{ cta_href }}" universal="true" target="_blank") {{ cta_label }}
